<?xml version="1.0" encoding="UTF-8"?>
<ArdourMIDIBindings version="1.0.0" name="Keystation 88 - Upper Controls" manufacturer="M-Audio">

  <DeviceInfo DeviceSendingPortRegex="Keystation 88 MIDI 2"/>

<!-- Transport Controls -->
  <Binding channel="1" note="93" function="transport-stop"/>
  <Binding channel="1" note="94" function="transport-roll"/>
  <Binding channel="1" note="95" function="toggle-rec-enable"/>


<!-- Cursor buttons-->
  <Binding channel="1" note="96"  action="Editor/scroll-tracks-down"/>
  <Binding channel="1" note="97"  action="Editor/scroll-tracks-up"/>
  <Binding channel="1" note="98"  action="Editor/scroll-backward"/>
  <Binding channel="1" note="99"  action="Editor/scroll-forward"/>
  <Binding channel="1" note="100" action="Transport/GotoStart"/>

</ArdourMIDIBindings>
